@MockitoSettings(strictness = Strictness.LENIENT)
public class SimplexTableau_getSolution_TriageGen2Test {

    @Spy
    private SimplexTableau tableauSpy;

    private LinearObjectiveFunction fMock;
    private RealVector fValueMock;

    @Before
    public void setUp() throws Exception {
        fMock = mock(LinearObjectiveFunction.class);
        fValueMock = mock(RealVector.class);

        // Use reflection to set the private field 'f' which is used in f.getValue(coefficients)
        Field fField = SimplexTableau.class.getDeclaredField("f");
        fField.setAccessible(true);
        fField.setSet(tableauSpy, fMock);

        // Mock basic tableau structure via spy
        doReturn(2).when(tableauSpy).getOriginalNumDecisionVariables();
        doReturn(1).when(tableauSpy).getNumObjectiveFunctions();
        doReturn(1).when(tableauSpy).getRhsOffset();

        // Default restrictToNonNegative to true for standard simplex
        Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableauSpy, true);
    }

    @Test
    public void testGetSolution_BasicSuccess() {
        // Setup: 2 decision variables, 1 objective function
        // Row 0: Objective, Row 1: Constraint 1, Row 2: RHS/Basic Row
        // Coefficients mapping: 
        // basicRow for obj: null (mostNegative = 0)
        // basicRow for var 0: row 1 (val 5.0)
        // basicRow for var 1: row 2 (val 3.0)

        doReturn(5.0).when(tableauSpy).getEntry(1, 1); // Assuming getRhsOffset is 1
        doReturn(3.0).when(tableauSpy).getEntry(2, 1);
        doReturn(1).when(tableauSpy).getBasicRow(1); // var 0
        doReturn(2).when(tableauSpy).getBasicRow(2); // var 1
        doReturn(null).when(tableauSpy).getBasicRow(1 + 2); // obj row check

        // Mock tableau for the inner loop check (tableau.getEntry(basicRow, j) == 1)
        // We need to mock the internal tableau field or the getEntry method
        doReturn(5.0).when(tableauSpy).getEntry(1, 1); 
        doReturn(3.0).when(tableauSpy).getEntry(2, 1);

        when(fMock.getValue(any(double[].class))).thenReturn(8.0);

        RealPointValuePair result = tableauSpy.getSolution();

        assertArrayEquals(new double[]{5.0, 3.0}, result.getPoint(), 1e-9);
        assertEquals(8.0, result.getValue(), 1e-9);
    }

    @Test
    public void testGetSolution_WithMostNegativeAndRestrictFalse() throws Exception {
        // Testing the logic: coefficients[i] = getEntry(...) - (restrictToNonNegative ? 0 : mostNegative)

        Field restrictField = SimplexTableau.class.getDeclaredField("restrictToNonNegative");
        restrictField.setAccessible(true);
        restrictField.set(tableauSpy, false);

        // getNumObjectiveFunctions() = 1
        // getOriginalNumDecisionVariables() = 1
        doReturn(1).when(tableauSpy).getOriginalNumDecisionVariables();
        doReturn(1).when(tableauSpy).getNumObjectiveFunctions();
        doReturn(1).when(tableauSpy).getRhsOffset();

        // mostNegative comes from getBasicRow(1 + 1) = getBasicRow(2)
        doReturn(2).when(tableauSpy).getBasicRow(2);
        doReturn(-10.0).when(tableauSpy).getEntry(2, 1); // mostNegative = -10.0

        // coefficient for var 0 comes from getBasicRow(1 + 0) = getBasicRow(1)
        doReturn(1).when(tableauSpy).getBasicRow(1);
        doReturn(5.0).when(tableauSpy).getEntry(1, 1);

        when(fMock.getValue(any(double[].class))).thenReturn(15.0);

        // Expected: 5.0 - (-10.0) = 15.0 (since restrictToNonNegative is false)
        RealPointValuePair result = tableauSpy.getSolution();
        assertArrayEquals(new double[]{15.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_WithZeroBasicRow() {
        doReturn(1).when(tableauSpy).getOriginalNumDecisionVariables();
        doReturn(1).when(tableauSpy).getNumObjectiveFunctions();
        doReturn(1).when(tableauSpy).getRhsOffset();

        // basicRow for objective is null -> mostNegative = 0
        doReturn(null).when(tableauSpy).getBasicRow(2);
        // basicRow for var 0 is null -> coefficients[0] = 0
        doReturn(null).when(tableauSpy).getBasicRow(1);

        when(fMock.getValue(any(double[].class))).thenReturn(0.0);

        RealPointValuePair result = tableauSpy.getSolution();
        assertArrayEquals(new double[]{0.0}, result.getPoint(), 1e-9);
    }

    @Test
    public void testGetSolution_WithColumnCheckLogic() throws Exception {
        // Testing the inner loop: if (tableau.getEntry(basicRow, j) == 1) { coefficients[i] = 0; }
        doReturn(2).when(tableauSpy).getOriginalNumDecisionVariables();
        doReturn(1).when(tableauSpy).getNumObjectiveFunctions();
        doReturn(1).when(tableauSpy).getRhsOffset();

        // Var 0: basicRow = 1. Loop j from 1 to 0 (no execution)
        doReturn(1).when(tableauSpy).getBasicRow(1);
        doReturn(5.0).when(tableauSpy).getEntry(1, 1);

        // Var 1: basicRow = 2. Loop j from 1 to 1.
        // If tableau.getEntry(2, 1) == 1, then coefficients[1] = 0
        doReturn(2).when(tableauSpy).getBasicRow(2);
        doReturn(3.0).when(tableauSpy).getEntry(2, 1); // The RHS value

        // We need to simulate the tableau.getEntry(basicRow, j) call
        // In the actual code it's tableau.getEntry(basicRow, j). 
        // Since tableauSpy IS the tableau, we mock it.
        // For var 1, j = 1.
        // Note: The loop in code is: for (int j = getNumObjectiveFunctions(); j < getNumObjectiveFunctions() + i; j++)
        // For i=1, j starts at 1 and goes to < 2. So j=1.
        // If getEntry(2, 1) == 1, coefficient becomes 0.
        // But getEntry(2, 1) is also used for the RHS. This is a specific edge case in the algorithm logic.

        // To trigger the 'if' inside the loop for i=1:
        // We need getEntry(2, 1) to be 1.0 (which is the RHS) AND we need to ensure it's called in the j loop.
        // But wait, if j=1 and getRhsOffset is 1, then getEntry(basicRow, j) is the same as getEntry(basicRow, getRhsOffset).

        doReturn(1.0).when(tableauSpy).getEntry(2, 1); 
        doReturn(null).when(tableauSpy).getBasicRow(3);

        when(fMock.getValue(any(double[].class))).thenReturn(5.0);

        RealPointValuePair result = tableauSpy.getSolution();

        // var 0: 5.0
        // var 1: getEntry(2,1) is 1.0. j loop: j=1. entry(2,1) is 1.0. So coefficients[1] = 0.
        assertArrayEquals(new double[]{5.0, 0.0}, result.getPoint(), 1e-9);
    }
}
